function tr(s){const k=s.trim();if(!k)return null;if(D[k])return D[k];for(const[r,v]of RX)if(r.test(k))return k.replace(r,v);if(k.includes(" · "))return k.split(" · ").map(x=>tr(x)||x).join(" · ");return null}
