function walk(root){const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT),L=[];let n;while(n=w.nextNode())L.push(n);
for(const n of L){if(n._o!==undefined||(n.parentNode.closest&&n.parentNode.closest("script,style,#lg,[data-nt]")))continue;const t=tr(n.nodeValue);if(t){n._o=n.nodeValue;n.nodeValue=n.nodeValue.replace(n.nodeValue.trim(),()=>t)}}
if(root.querySelectorAll)root.querySelectorAll("[placeholder],[aria-label]").forEach(e=>{for(const a of["placeholder","aria-label"]){const v=e.getAttribute(a);if(v&&!e["_"+a]){const t=tr(v);if(t){e["_"+a]=v;e.setAttribute(a,t)}}}})}
new MutationObserver(m=>{if(lang!="ar")return;m.forEach(r=>r.addedNodes.forEach(x=>{if(x.nodeType==1)walk(x);else if(x.nodeType==3&&x.parentNode)walk(x.parentNode)}))}).observe(document.body,{childList:true,subtree:true});
