function mkSl(id){const el=$(id);el.className="sl";let tm;
const go=d=>{const sw=el.firstElementChild.offsetWidth+16,rtl=document.documentElement.dir=="rtl",mx=el.scrollWidth-el.clientWidth;let p=Math.abs(el.scrollLeft)+d*sw;if(p>mx+4)p=0;if(p<0)p=mx;el.scrollTo({left:rtl?-p:p,behavior:"smooth"})};
const run=()=>{clearInterval(tm);if(!RM)tm=setInterval(()=>go(1),4200)};run();
el.onmouseenter=()=>clearInterval(tm);el.onmouseleave=run;el.ontouchstart=()=>clearInterval(tm);
el.insertAdjacentHTML("afterend",`<div class="sa"><button aria-label="Previous">‹</button><button aria-label="Next">›</button></div>`);
const b=el.nextElementSibling.children;b[0].onclick=()=>{go(-1);run()};b[1].onclick=()=>{go(1);run()}}
